    INSERT INTO mcqs (topic_id, question, options, correct_index, explanation) VALUES
    (v_topic_id, 'A 55-year-old heavy smoker presents with a white, adherent patch on the lateral tongue that cannot be scraped off. What is the most appropriate next step in management?', '["Antifungal mouthwash", "Excisional biopsy", "Incisional biopsy", "Observation", "Topical corticosteroids"]'::jsonb, 2, 'The patient has clinical leukoplakia, a premalignant lesion. Because it is a diagnosis of exclusion and carries a risk of squamous cell carcinoma or dysplasia, a biopsy (incisional for larger lesions, to sample the most suspicious area) is the standard of care to establish a tissue diagnosis.'),
    (v_topic_id, 'Which of the following oral lesions carries the highest statistical risk of undergoing malignant transformation?', '["Erythroplakia", "Leukoplakia", "Lichen planus", "Oral candidiasis", "Aphthous ulcer"]'::jsonb, 0, 'Erythroplakia (a red velvety patch) has a much higher rate of dysplasia or frankly invasive carcinoma at the time of biopsy compared to leukoplakia, with up to 90% harboring severe dysplasia or SCC.'),
    (v_topic_id, 'What is the most common site for squamous cell carcinoma within the oral cavity in Western countries?', '["Hard palate", "Buccal mucosa", "Dorsum of the tongue", "Ventral-lateral surface of the tongue", "Gingiva"]'::jsonb, 3, 'The ventral-lateral surface of the tongue and the floor of the mouth are the most common sites for oral cavity SCC, likely because carcinogens from tobacco and alcohol pool in these dependent areas.'),
    (v_topic_id, 'A 60-year-old man presents with a 2-cm indurated, non-healing ulcer on his lower lip. What is the most significant risk factor for this specific malignancy?', '["Human papillomavirus (HPV) infection", "Chronic sun (ultraviolet) exposure", "Smokeless tobacco use", "Alcohol consumption", "Epstein-Barr virus (EBV)"]'::jsonb, 1, 'Squamous cell carcinoma of the lip (specifically the lower lip, which receives more direct sunlight) is overwhelmingly associated with chronic ultraviolet radiation exposure, causing actinic cheilitis as a precursor.'),
    (v_topic_id, 'Which lymph node basin is the primary drainage site for the central portion of the lower lip?', '["Submandibular nodes (Level IB)", "Submental nodes (Level IA)", "Upper jugular nodes (Level II)", "Preauricular nodes", "Supraclavicular nodes"]'::jsonb, 1, 'The central lower lip and the anterior floor of the mouth drain primarily into the submental lymph nodes (Level IA). The lateral lower lip drains into the submandibular nodes.'),
    (v_topic_id, 'A patient with a T2 squamous cell carcinoma of the lateral oral tongue undergoes a partial glossectomy. What additional surgical procedure is typically indicated?', '["Elective neck dissection", "Total glossectomy", "Mandibulectomy", "Parotidectomy", "Tracheostomy"]'::jsonb, 0, 'Oral tongue SCC has a high propensity for occult cervical lymph node metastasis (often >20% even in early stages). Therefore, an elective neck dissection (usually levels I-III or I-IV) is indicated for staging and regional control.'),
    (v_topic_id, 'A 65-year-old alcoholic presents with a hard mass in the anterior floor of the mouth. The tumor is found to be invading the lingual cortex of the mandible. What is the appropriate surgical management regarding the bone?', '["Tooth extraction only", "Marginal mandibulectomy", "Segmental mandibulectomy", "No bone resection is needed", "Radiation therapy alone"]'::jsonb, 1, 'If the tumor invades only the superficial cortex but does not invade the medullary space, a marginal mandibulectomy (removing the inner cortex but preserving the inferior mandibular border for continuity) is appropriate.'),
    (v_topic_id, 'A 70-year-old farmer who has chewed tobacco for 40 years presents with a large, exophytic, warty mass on his buccal mucosa. Biopsy shows a very well-differentiated squamous proliferation with "pushing" rather than infiltrating borders. What is the diagnosis?', '["Ameloblastoma", "Verrucous carcinoma", "Pleomorphic adenoma", "Basal cell carcinoma", "Mucoepidermoid carcinoma"]'::jsonb, 1, 'Verrucous carcinoma (Ackerman''s tumor) is a low-grade variant of SCC associated with smokeless tobacco. It is locally destructive but rarely metastasizes to lymph nodes. It typically features "pushing" deep margins.'),
    (v_topic_id, 'What is the standard treatment for verrucous carcinoma of the oral cavity?', '["Primary radiation therapy", "Surgical excision", "Systemic chemotherapy", "Observation", "Topical imiquimod"]'::jsonb, 1, 'Surgical excision is the treatment of choice. Radiation therapy is generally avoided, as there is a historical (though debated) concern for inducing anaplastic transformation into a more aggressive tumor.'),
    (v_topic_id, 'A patient presents with a hard, 3-cm mass in the midline of the hard palate. The overlying mucosa is intact. Biopsy reveals a malignant salivary gland tumor. What is the most likely diagnosis?', '["Squamous cell carcinoma", "Pleomorphic adenoma", "Adenoid cystic carcinoma", "Warthin tumor", "Acinic cell carcinoma"]'::jsonb, 2, 'The hard palate is a common site for minor salivary gland tumors. While pleomorphic adenoma is the most common benign tumor, adenoid cystic carcinoma and mucoepidermoid carcinoma are the most common malignancies here.'),
    (v_topic_id, 'During excision of a submandibular gland for a benign tumor, which nerve is at risk of injury as it loops under Wharton''s duct?', '["Facial nerve (marginal mandibular branch)", "Hypoglossal nerve", "Lingual nerve", "Glossopharyngeal nerve", "Recurrent laryngeal nerve"]'::jsonb, 2, 'The lingual nerve provides sensation to the anterior 2/3 of the tongue and classically loops under the submandibular (Wharton''s) duct in the floor of the mouth.'),
    (v_topic_id, 'Injury to the hypoglossal nerve during a neck dissection will result in which clinical finding?', '["Loss of taste to the anterior 2/3 of the tongue", "Deviation of the tongue to the contralateral side upon protrusion", "Deviation of the tongue to the ipsilateral side upon protrusion", "Numbness of the lower lip", "Inability to elevate the soft palate"]'::jsonb, 2, 'The hypoglossal nerve (CN XII) provides motor innervation to the intrinsic and extrinsic tongue muscles. Injury causes the tongue to deviate toward the side of the lesion due to the unopposed action of the contralateral genioglossus muscle.'),
    (v_topic_id, 'A 45-year-old woman presents with a slowly growing, painless mass in the tail of the parotid gland. Fine-needle aspiration demonstrates a mixture of epithelial cells and chondromyxoid stroma. What is the diagnosis?', '["Warthin tumor", "Mucoepidermoid carcinoma", "Pleomorphic adenoma", "Acinic cell carcinoma", "Schwannoma"]'::jsonb, 2, 'Pleomorphic adenoma (benign mixed tumor) is the most common tumor of the parotid gland. The classic cytologic finding is a mixture of epithelial/myoepithelial cells and a mesenchymal-like (chondromyxoid) stroma.'),
    (v_topic_id, 'Why is a formal superficial parotidectomy favored over simple enucleation for a pleomorphic adenoma of the superficial parotid lobe?', '["To prevent facial nerve injury", "To sample intraparotid lymph nodes", "Because the tumor lacks a true capsule and has pseudopod extensions", "To rule out distant metastasis", "To preserve salivary flow"]'::jsonb, 2, 'Pleomorphic adenomas have microscopic pseudopod extensions that penetrate their pseudocapsule. Simple enucleation ("shelling out") leaves these extensions behind, leading to a high rate of multifocal recurrence.'),
    (v_topic_id, 'A 60-year-old male smoker presents with bilateral, soft, cystic masses at the angles of his jaw. A technetium-99m scan shows intense bilateral uptake. What is the most likely diagnosis?', '["Bilateral pleomorphic adenomas", "Warthin tumor", "Sjogren''s syndrome", "Sialadenosis", "Mucoepidermoid carcinoma"]'::jsonb, 1, 'Warthin tumor (papillary cystadenoma lymphomatosum) is strongly associated with smoking, frequently presents bilaterally (in 10-15% of cases), feels cystic, and uniquely concentrates technetium-99m.'),
    (v_topic_id, 'What is the characteristic histological appearance of a Warthin tumor?', '["Spindle cells in a palisading arrangement", "A double layer of oncocytic epithelium forming cystic spaces with a dense lymphoid stroma", "Mucin-producing cells and epidermoid cells", "Basaloid cells in a cribriform (Swiss-cheese) pattern", "Clear cells with abundant glycogen"]'::jsonb, 1, 'The histologic hallmark of Warthin tumor is the bilayered oncocytic epithelium accompanied by a dense lymphoid stroma (often with germinal centers).'),
    (v_topic_id, 'According to the "Rule of 80s" for salivary gland neoplasms, what percentage of parotid tumors are benign?', '["20%", "50%", "80%", "90%", "100%"]'::jsonb, 2, 'Roughly 80% of salivary gland tumors occur in the parotid, and about 80% of parotid tumors are benign. Conversely, sublingual tumors are rare, but ~80% are malignant.'),
    (v_topic_id, 'A patient with a history of radiation therapy for childhood lymphoma develops a firm parotid mass 20 years later. What is the most likely malignant diagnosis?', '["Adenoid cystic carcinoma", "Acinic cell carcinoma", "Mucoepidermoid carcinoma", "Squamous cell carcinoma", "Malignant melanoma"]'::jsonb, 2, 'Mucoepidermoid carcinoma is the most common salivary gland malignancy and is the most common radiation-induced salivary neoplasm.'),
    (v_topic_id, 'A 30-year-old woman with anorexia nervosa presents with painless, bilateral swelling of her cheeks. Her salivary flow is normal, and she has no dry mouth. What is the condition?', '["Sjogren''s syndrome", "Acute suppurative parotitis", "Sialadenosis (sialosis)", "Warthin tumor", "Mumps"]'::jsonb, 2, 'Sialadenosis is a non-neoplastic, non-inflammatory bilateral enlargement of the parotid glands (acinar hypertrophy) associated with systemic conditions like eating disorders, alcoholism, diabetes, and malnutrition.'),
    (v_topic_id, 'What is the most appropriate management for sialadenosis?', '["Bilateral superficial parotidectomy", "Treatment of the underlying systemic condition", "High-dose oral corticosteroids", "Antibiotics", "Radiation therapy"]'::jsonb, 1, 'Because sialadenosis is a systemic autonomic neuropathy causing acinar hypertrophy, the treatment is purely medical, focusing on correcting the underlying nutritional, endocrine, or metabolic disorder.'),
    (v_topic_id, 'Which salivary gland tumor is notorious for its high propensity for perineural invasion?', '["Pleomorphic adenoma", "Warthin tumor", "Acinic cell carcinoma", "Adenoid cystic carcinoma", "Polymorphous low-grade adenocarcinoma"]'::jsonb, 3, 'Adenoid cystic carcinoma has a striking tendency to spread along nerve sheaths (perineural invasion), often leading to pain or cranial nerve deficits (e.g., facial paralysis) and a high rate of local recurrence.'),
    (v_topic_id, 'A patient undergoes resection of an adenoid cystic carcinoma of the submandibular gland. Which nerve pathway should be specifically evaluated and potentially included in the postoperative radiation field?', '["Facial nerve", "Lingual and trigeminal nerve pathways up to the skull base", "Vagus nerve", "Accessory nerve", "Phrenic nerve"]'::jsonb, 1, 'Due to perineural invasion, the tumor can travel retrograde along the lingual nerve to the mandibular division of the trigeminal nerve (V3) and into the skull base via the foramen ovale.'),
    (v_topic_id, 'What is the most common presentation of a benign minor salivary gland tumor of the palate?', '["A painful, ulcerated lesion", "A smooth, painless, submucosal swelling", "A rapidly expanding cystic mass", "A bleeding, exophytic mass", "A flat, white plaque"]'::jsonb, 1, 'Benign tumors of the minor salivary glands, such as pleomorphic adenomas, typically present as slow-growing, painless, firm, submucosal masses with intact overlying mucosa.'),
    (v_topic_id, 'A 50-year-old man presents with a hard mass in the deep lobe of the parotid gland that bulges into the oropharynx, pushing the tonsil medially. What is this space called?', '["Retropharyngeal space", "Parapharyngeal space", "Submandibular space", "Masticator space", "Prevertebral space"]'::jsonb, 1, 'Tumors of the deep lobe of the parotid expand into the parapharyngeal space, often presenting as an asymptomatic bulge in the lateral pharyngeal wall and tonsillar fossa.'),
    (v_topic_id, 'Which imaging modality is preferred for evaluating a suspected parapharyngeal space tumor?', '["Ultrasound", "Plain radiograph", "CT or MRI with contrast", "PET scan", "Sialography"]'::jsonb, 2, 'CT or MRI is essential to delineate the tumor''s relationship to the great vessels (carotid artery, jugular vein) and to determine if it arises from the deep lobe of the parotid or is a primary neurogenic tumor/paraganglioma.'),
    (v_topic_id, 'During a superficial parotidectomy, the surgeon identifies the facial nerve trunk. Which bony landmark is most reliable for finding the main trunk of the facial nerve as it exits the stylomastoid foramen?', '["The mastoid tip", "The angle of the mandible", "The tympanomastoid suture line", "The zygomatic arch", "The styloid process"]'::jsonb, 2, 'The tympanomastoid suture line is a highly reliable, constant bony landmark; the facial nerve trunk lies approximately 6-8 mm deep and slightly inferior to the medial end of this suture (the pointer).'),
    (v_topic_id, 'A patient develops facial asymmetry and weakness after a parotidectomy but has normal eye closure. Which branch of the facial nerve was likely injured?', '["Temporal branch", "Zygomatic branch", "Buccal branch", "Marginal mandibular branch", "Cervical branch"]'::jsonb, 3, 'The marginal mandibular branch innervates the depressors of the lower lip. Injury results in an inability to pull the lower lip down and outwards on the affected side, creating an asymmetric smile.'),
    (v_topic_id, 'What is Frey''s syndrome (gustatory sweating)?', '["Sweating over the parotid area while eating due to aberrant reinnervation of sweat glands by parasympathetic fibers", "Dry mouth and dry eyes from autoimmune destruction", "Excessive salivation causing drooling", "Facial twitching during mastication", "Pain in the ear when swallowing"]'::jsonb, 0, 'After parotidectomy, severed parasympathetic secretomotor fibers (which normally innervate the parotid) can aberrantly regenerate and innervate the sympathetic receptors of the sweat glands in the overlying skin.'),
    (v_topic_id, 'A 60-year-old man presents with a long-standing pleomorphic adenoma that suddenly begins growing rapidly and causes facial nerve paralysis. What is the most likely diagnosis?', '["Transformation into Warthin tumor", "Carcinoma ex pleomorphic adenoma", "Metastatic squamous cell carcinoma", "Infection of the adenoma", "Hemorrhage into the tumor"]'::jsonb, 1, 'Long-standing pleomorphic adenomas (especially those present for >10 years) carry a risk of malignant transformation into Carcinoma ex Pleomorphic Adenoma, characterized by rapid growth, pain, and facial nerve involvement.'),
    (v_topic_id, 'Which of the following salivary gland malignancies is graded (low, intermediate, high) based on the proportion of cystic spaces, necrosis, neural invasion, and mitoses?', '["Adenoid cystic carcinoma", "Acinic cell carcinoma", "Mucoepidermoid carcinoma", "Squamous cell carcinoma", "Clear cell carcinoma"]'::jsonb, 2, 'Mucoepidermoid carcinoma is unique among salivary tumors in that its histologic grade strongly dictates its clinical behavior and the required aggressiveness of treatment.'),
    (v_topic_id, 'A 45-year-old female presents with a 2-cm mass in the right parotid. FNA demonstrates acinic cell carcinoma. The facial nerve is completely functional. What is the appropriate surgical management?', '["Enucleation", "Superficial parotidectomy with facial nerve preservation", "Total parotidectomy with facial nerve sacrifice", "Observation", "Radiation therapy only"]'::jsonb, 1, 'Acinic cell carcinoma is generally a low-grade malignancy. Superficial parotidectomy with preservation of the facial nerve (if it is not directly invaded) is the standard of care.'),
    (v_topic_id, 'Which salivary gland is almost exclusively affected by Acinic Cell Carcinoma?', '["Submandibular gland", "Sublingual gland", "Minor salivary glands of the lip", "Parotid gland", "Palatal glands"]'::jsonb, 3, 'Acinic cell carcinoma represents a malignant proliferation of serous acinar cells. Since the parotid is the only purely serous salivary gland, the vast majority (>80%) of these tumors arise there.'),
    (v_topic_id, 'What is the characteristic cytologic feature of Acinic Cell Carcinoma on fine needle aspiration?', '["Intracellular mucin droplets", "Basophilic zymogen granules", "Perineural palisading", "Keratin pearls", "Amyloid stroma"]'::jsonb, 1, 'The cells of acinic cell carcinoma attempt to mimic normal serous acinar cells and therefore contain distinct basophilic zymogen granules in their cytoplasm.'),
    (v_topic_id, 'Which of the following is a classic risk factor for the development of salivary gland malignancies?', '["Alcohol consumption", "Chewing tobacco", "Prior head and neck radiation exposure", "Human papillomavirus (HPV) infection", "Epstein-Barr virus (EBV) infection"]'::jsonb, 2, 'Radiation exposure (such as mantle field radiation for Hodgkin''s lymphoma or dental x-rays historically) is a well-documented risk factor for salivary gland cancer, particularly mucoepidermoid carcinoma.'),
    (v_topic_id, 'A 50-year-old man presents with a submandibular gland mass. Excision reveals a tumor composed of a uniform population of basaloid cells forming cystic spaces filled with a basophilic mucoid material (Swiss-cheese pattern). What is the diagnosis?', '["Pleomorphic adenoma", "Warthin tumor", "Mucoepidermoid carcinoma", "Adenoid cystic carcinoma", "Polymorphous low-grade adenocarcinoma"]'::jsonb, 3, 'This perfectly describes the cribriform (Swiss-cheese) histologic variant of Adenoid Cystic Carcinoma, which is the most classic and recognizable pattern of the disease.'),
    (v_topic_id, 'Which histologic subtype of Adenoid Cystic Carcinoma carries the worst prognosis?', '["Tubular", "Cribriform", "Solid", "Papillary", "Follicular"]'::jsonb, 2, 'The solid variant of adenoid cystic carcinoma is more aggressive, has a higher mitotic rate, metastasizes earlier, and carries a significantly worse prognosis than the cribriform or tubular variants.'),
    (v_topic_id, 'What is the characteristic pattern of metastasis for Adenoid Cystic Carcinoma?', '["Early massive cervical lymphadenopathy", "Rapid hematogenous spread to the brain", "Late hematogenous spread, most commonly to the lungs", "Direct extension into the mediastinum", "Spread via the cerebrospinal fluid"]'::jsonb, 2, 'ACC is notorious for an indolent but relentless course, with patients frequently developing distant metastases (especially to the lungs) 10 to 20 years after the initial treatment.'),
    (v_topic_id, 'A patient is diagnosed with a 4-cm mucoepidermoid carcinoma of the parotid gland. Pathology reveals it is high-grade. What does the treatment plan typically involve?', '["Superficial parotidectomy alone", "Total parotidectomy, neck dissection, and postoperative radiation", "Systemic chemotherapy alone", "Observation", "Radioactive iodine ablation"]'::jsonb, 1, 'High-grade mucoepidermoid carcinoma behaves aggressively, much like a squamous cell carcinoma. It requires aggressive surgery (often total parotidectomy, ipsilateral neck dissection for nodal risk) followed by postoperative radiation.'),
    (v_topic_id, 'What structure divides the parotid gland into a "superficial" and "deep" lobe for surgical purposes?', '["The retromandibular vein", "The external carotid artery", "The facial nerve", "The masseter muscle", "The parotid duct (Stensen''s duct)"]'::jsonb, 2, 'The parotid gland is not anatomically divided by a true fascia, but surgically it is divided by the plane of the facial nerve into a superficial lobe (lateral to the nerve) and a deep lobe (medial to the nerve).'),
    (v_topic_id, 'Which muscle does the parotid duct (Stensen''s duct) pierce before entering the oral cavity?', '["Masseter", "Buccinator", "Medial pterygoid", "Orbicularis oris", "Temporalis"]'::jsonb, 1, 'Stensen''s duct runs anteriorly over the masseter muscle, turns medially to pierce the buccinator muscle, and opens into the oral cavity opposite the second maxillary molar.'),
    (v_topic_id, 'A biopsy of an ulcerated palatal mass shows "pseudoepitheliomatous hyperplasia" overlying a deep necrotizing salivary gland inflammation. What is this benign condition that mimics malignancy?', '["Pleomorphic adenoma", "Necrotizing sialometaplasia", "Mucous extravasation phenomenon (ranula)", "Torus palatinus", "Actinomycosis"]'::jsonb, 1, 'Necrotizing sialometaplasia is a benign, self-limiting inflammatory condition of the minor salivary glands (usually on the hard palate) caused by ischemia. Its clinical and histologic appearance can closely mimic squamous cell or mucoepidermoid carcinoma.'),
    (v_topic_id, 'A 10-year-old child presents with a painless, bluish, fluctuant mass in the floor of the mouth lateral to the midline. What is the most likely diagnosis?', '["Dermoid cyst", "Thyroglossal duct cyst", "Ranula", "Hemangioma", "Lymphangioma"]'::jsonb, 2, 'A ranula is a mucous retention cyst or extravasation pseudocyst arising from the sublingual gland in the floor of the mouth. It typically has a characteristic bluish, translucent appearance.'),
    (v_topic_id, 'What is the treatment for a plunging ranula (one that extends through the mylohyoid muscle into the neck)?', '["Marsupialization alone", "Excision of the cyst only", "Excision of the cyst and the ipsilateral submandibular gland", "Excision of the ipsilateral sublingual gland (with or without cyst excision)", "Aspiration"]'::jsonb, 3, 'Because the sublingual gland is the source of the mucin leak, excision of the sublingual gland is required to prevent recurrence of a plunging ranula.'),
    (v_topic_id, 'What is the most common site of metastasis for malignant salivary gland tumors?', '["Liver", "Brain", "Bone", "Lungs", "Kidneys"]'::jsonb, 3, 'When salivary gland malignancies disseminate hematogenously, the lungs are by far the most common site of distant metastasis.'),
    (v_topic_id, 'A patient presents with a slowly enlarging parotid mass. He is otherwise healthy. Fine-needle aspiration is non-diagnostic. What is the most appropriate next step?', '["Incisional biopsy through the skin", "Core needle biopsy", "Superficial parotidectomy for diagnosis and treatment", "Observation with repeat FNA in 6 months", "Radiation therapy"]'::jsonb, 2, 'Open incisional biopsy of a parotid mass is contraindicated due to the risk of tumor spillage (seeding the field) and facial nerve injury. Superficial parotidectomy is the standard diagnostic and therapeutic procedure.'),
    (v_topic_id, 'Which benign salivary gland tumor is known to occasionally present with multiple, separate nodules within the same gland (multicentricity)?', '["Pleomorphic adenoma", "Oncocytoma", "Warthin tumor", "Basal cell adenoma", "Canalicular adenoma"]'::jsonb, 2, 'Warthin tumor is notable for being multifocal in the same gland and bilateral in a significant percentage of patients.'),
    (v_topic_id, 'A 50-year-old woman presents with dry eyes, dry mouth, and bilateral parotid swelling. She also has rheumatoid arthritis. What is her diagnosis?', '["Sialadenosis", "Sjogren''s syndrome", "Mikulicz disease", "Sarcoidosis", "IgG4-related disease"]'::jsonb, 1, 'Sjogren''s syndrome is an autoimmune exocrinopathy causing xerostomia and xerophthalmia, often associated with other connective tissue diseases like rheumatoid arthritis or lupus.'),
    (v_topic_id, 'Patients with Sjogren''s syndrome have a significantly increased risk (up to 44 times normal) of developing which of the following malignancies?', '["Squamous cell carcinoma", "Mucoepidermoid carcinoma", "Non-Hodgkin''s lymphoma", "Adenoid cystic carcinoma", "Malignant melanoma"]'::jsonb, 2, 'The chronic intense lymphoid proliferation in Sjogren''s syndrome predisposes these patients to the development of B-cell non-Hodgkin''s lymphoma, often a MALT (mucosa-associated lymphoid tissue) lymphoma within the parotid gland.'),
    (v_topic_id, 'A rapidly expanding parotid mass in a patient with long-standing Sjogren''s syndrome should immediately raise suspicion for:', '["Acute suppurative parotitis", "A benign pleomorphic adenoma", "Lymphoma", "Sialolithiasis", "Warthin tumor"]'::jsonb, 2, 'Due to their highly elevated risk, any new, rapidly growing, or firm nodule in a Sjogren''s patient must be evaluated promptly for lymphoma.'),
    (v_topic_id, 'What autoantibodies are classically associated with Sjogren''s syndrome?', '["Anti-dsDNA and Anti-Sm", "Anti-Ro (SS-A) and Anti-La (SS-B)", "Anti-CCP and Rheumatoid Factor", "c-ANCA", "Anti-centromere"]'::jsonb, 1, 'Anti-Ro (SS-A) and Anti-La (SS-B) are the classic autoantibodies tested in the workup of primary Sjogren''s syndrome.')
